// Node 18+ (built-in fetch). Submit in the background and poll until the job ends.
const BASE_URL = "https://api.fanar.qa";
const API_KEY = "YOUR_API_KEY_HERE";
const headers = { Authorization: `Bearer ${API_KEY}`, "Content-Type": "application/json" };

type JobStatus = "queued" | "in_progress" | "completed" | "failed" | "cancelled" | "incomplete";

interface Job {
  id: string;
  status: JobStatus;
  progress_pct: number;
  result: { title: string; overview: string; markdown?: string } | null;
  error: { code: string; message: string } | null;
  incomplete_details: { reason: string } | null;
}

async function call(path: string, init?: RequestInit): Promise<Job> {
  const res = await fetch(`${BASE_URL}${path}`, { ...init, headers });
  if (!res.ok) throw new Error(`HTTP ${res.status}: ${await res.text()}`);
  return (await res.json()) as Job;
}

async function main(): Promise<void> {
  let job = await call("/v1/sadiq/deep-research", {
    method: "POST",
    body: JSON.stringify({
      model: "Fanar-Sadiq-2",
      input: "The importance of seeking knowledge in Islam",
      depth: "standard",
      background: true,
    }),
  });
  console.log(`job ${job.id}: ${job.status}`);

  while (job.status === "queued" || job.status === "in_progress") {
    await new Promise((resolve) => setTimeout(resolve, 10_000));
    job = await call(`/v1/sadiq/deep-research/${job.id}`);
    console.log(`${job.status} ${job.progress_pct}%`);
  }

  if (job.status === "completed" && job.result) {
    console.log(job.result.title);
    console.log(job.result.markdown ?? job.result.overview);
  } else if (job.status === "incomplete") {
    console.log("stopped by a content filter:", job.incomplete_details?.reason);
  } else {
    throw new Error(`${job.status}: ${job.error?.message}`);
  }
}

main().catch((err) => {
  console.error(err.message);
  process.exit(1);
});

# The job's events stream on this connection; its id is in the X-Id header.
# A response that ends without `data: [DONE]` is resumed from the last event id.

import json
import time

import requests

BASE_URL = "https://api.fanar.qa"
API_KEY = "YOUR_API_KEY_HERE"
HEADERS = {"Authorization": f"Bearer {API_KEY}"}


def follow(response, state):
    """Read events until [DONE] (True) or the response ends (False)."""
    event_id = None
    for line in response.iter_lines(decode_unicode=True):
        if line.startswith("id: "):
            event_id = line[4:]
        elif line.startswith("data: "):
            state["last_id"] = event_id
            data = line[6:]
            if data == "[DONE]":
                return True
            chunk = json.loads(data)
            if "progress" in chunk:
                print("...", chunk["progress"]["message"]["en"])
            elif "report" in chunk:
                # Use the report as the result, not the concatenated deltas. If a
                # worker fails, the job restarts and its events replay from the start
                # once -- the report is still the one to keep.
                state["report"] = chunk["report"]
    return False


state = {"last_id": None, "report": None}
with requests.post(
    f"{BASE_URL}/v1/sadiq/deep-research",
    headers=HEADERS,
    json={
        "model": "Fanar-Sadiq-2",
        "input": "The importance of seeking knowledge in Islam",
        "depth": "standard",
        "background": True,
        "stream": True,
    },
    stream=True,
    timeout=(10, 120),  # a keepalive arrives every 15 seconds of quiet
) as response:
    response.raise_for_status()
    job_id = response.headers["X-Id"]
    try:
        done = follow(response, state)
    except requests.RequestException:
        done = False  # the job does not depend on this connection; resume below

while not done:
    try:
        with requests.get(
            f"{BASE_URL}/v1/sadiq/deep-research/{job_id}",
            headers=HEADERS,
            params={"stream": "true", "starting_after": state["last_id"]},
            stream=True,
            timeout=(10, 120),
        ) as response:
            response.raise_for_status()
            done = follow(response, state)
    except requests.HTTPError as exc:
        if exc.response.status_code < 500 and exc.response.status_code != 429:
            raise  # 404: gone or never yours -- stop
        time.sleep(2)
    except requests.RequestException:
        time.sleep(2)  # dropped, mid-event or before connecting: resume from the last id

# The job object is the authoritative outcome: completed, failed, cancelled, incomplete.
job = requests.get(f"{BASE_URL}/v1/sadiq/deep-research/{job_id}", headers=HEADERS, timeout=30).json()
print(job["status"])
if job["status"] == "completed":
    print(job["result"]["title"])

