# Follow a job's events to the end, from its first event, surviving any number of
# dropped or closed connections. Each event's `id:` is a resume point.

import json
import time

import requests

BASE_URL = "https://api.fanar.qa"
API_KEY = "YOUR_API_KEY_HERE"
JOB_ID = "YOUR_JOB_ID"


def events(job_id, after):
    """(id, payload) for each event after `after`, until the response ends."""
    with requests.get(
        f"{BASE_URL}/v1/sadiq/deep-research/{job_id}",
        headers={"Authorization": f"Bearer {API_KEY}"},
        params={"stream": "true", "starting_after": after},
        stream=True,
        timeout=(10, 120),  # a keepalive arrives every 15 seconds of quiet
    ) as response:
        response.raise_for_status()
        event_id = None
        for line in response.iter_lines(decode_unicode=True):
            if line.startswith("id: "):
                event_id = line[4:]
            elif line.startswith("data: "):
                yield event_id, line[6:]


last_id, report, done = None, None, False
while not done:
    try:
        for event_id, data in events(JOB_ID, last_id):
            last_id = event_id
            if data == "[DONE]":
                done = True
                break
            chunk = json.loads(data)
            if "progress" in chunk:
                print("...", chunk["progress"]["message"]["en"])
            elif "report" in chunk:
                report = chunk["report"]  # the result to keep
            elif "error" in chunk:
                print("error:", chunk["error"].get("message"))
    except requests.HTTPError as exc:
        # 404: unknown, created under a different access, or past retention -- stop.
        if exc.response.status_code < 500 and exc.response.status_code != 429:
            raise
        time.sleep(2)
    except requests.RequestException:
        # Dropped, mid-event or before connecting: resume from the last id.
        time.sleep(2)
    # Fell out without [DONE]: the server closed this response on purpose. Resume.

print(report["title"] if report else "no report (see the job's status)")

// Node 18+ (built-in fetch). Follow a job's events to the end, resuming from the last
// event id after every closed or dropped connection.
const BASE_URL = "https://api.fanar.qa";
const API_KEY = "YOUR_API_KEY_HERE";
const JOB_ID = "YOUR_JOB_ID";
const headers = { Authorization: `Bearer ${API_KEY}` };

class Fatal extends Error {}

interface Chunk {
  progress?: { message: { en: string } };
  report?: { title: string };
  error?: { message?: string };
}

// One response. True on [DONE]; false when it ends without it (resume).
async function readSegment(state: { lastId: string | null }, onChunk: (c: Chunk) => void): Promise<boolean> {
  const url = new URL(`${BASE_URL}/v1/sadiq/deep-research/${JOB_ID}`);
  url.searchParams.set("stream", "true");
  if (state.lastId) url.searchParams.set("starting_after", state.lastId);
  const res = await fetch(url, { headers });
  if (res.status >= 400 && res.status < 500 && res.status !== 429) {
    throw new Fatal(`HTTP ${res.status}: ${await res.text()}`); // e.g. 404: unknown job
  }
  if (!res.ok || !res.body) throw new Error(`HTTP ${res.status}`);

  const decoder = new TextDecoder();
  let buffer = "";
  for await (const bytes of res.body as unknown as AsyncIterable<Uint8Array>) {
    buffer += decoder.decode(bytes, { stream: true });
    let end: number;
    while ((end = buffer.indexOf("\n\n")) !== -1) {
      const block = buffer.slice(0, end);
      buffer = buffer.slice(end + 2);
      let id: string | null = null;
      let data: string | null = null;
      for (const line of block.split("\n")) {
        if (line.startsWith("id: ")) id = line.slice(4);
        else if (line.startsWith("data: ")) data = line.slice(6);
      }
      if (data === null) continue; // keepalive
      state.lastId = id ?? state.lastId;
      if (data === "[DONE]") return true;
      onChunk(JSON.parse(data) as Chunk);
    }
  }
  return false;
}

async function follow(): Promise<void> {
  const state = { lastId: null as string | null };
  let report: Chunk["report"] | null = null;
  const onChunk = (chunk: Chunk) => {
    if (chunk.progress) console.log("...", chunk.progress.message.en);
    else if (chunk.report) report = chunk.report; // the result to keep
    else if (chunk.error) console.log("error:", chunk.error.message);
  };
  for (;;) {
    try {
      if (await readSegment(state, onChunk)) break;
    } catch (err) {
      if (err instanceof Fatal) throw err;
      await new Promise((resolve) => setTimeout(resolve, 2000));
    }
  }
  console.log(report ? (report as { title: string }).title : "no report (see the job's status)");
}

follow().catch((err) => {
  console.error(err.message);
  process.exit(1);
});

# Cancellation is asynchronous, and a job already finishing may complete anyway:
# check the status you end with.

import time

import requests

BASE_URL = "https://api.fanar.qa"
API_KEY = "YOUR_API_KEY_HERE"
HEADERS = {"Authorization": f"Bearer {API_KEY}"}
JOB_ID = "YOUR_JOB_ID"

job = requests.post(
    f"{BASE_URL}/v1/sadiq/deep-research/{JOB_ID}/cancel", headers=HEADERS, timeout=30
).json()

while job["status"] in ("queued", "in_progress"):
    time.sleep(1)
    job = requests.get(
        f"{BASE_URL}/v1/sadiq/deep-research/{JOB_ID}", headers=HEADERS, timeout=30
    ).json()

if job["status"] == "cancelled":
    print("cancelled")
