// Node 18+. Cancellation is asynchronous, and a job already finishing may complete
// anyway: check the status you end with.
const BASE_URL = "https://api.fanar.qa";
const API_KEY = "YOUR_API_KEY_HERE";
const JOB_ID = "YOUR_JOB_ID";
const headers = { Authorization: `Bearer ${API_KEY}` };

interface Job { id: string; status: string }

async function call(path: string, method = "GET"): Promise<Job> {
  const res = await fetch(`${BASE_URL}${path}`, { method, headers });
  if (!res.ok) throw new Error(`HTTP ${res.status}: ${await res.text()}`);
  return (await res.json()) as Job;
}

async function main(): Promise<void> {
  let job = await call(`/v1/sadiq/deep-research/${JOB_ID}/cancel`, "POST");
  while (job.status === "queued" || job.status === "in_progress") {
    await new Promise((resolve) => setTimeout(resolve, 1000));
    job = await call(`/v1/sadiq/deep-research/${JOB_ID}`);
  }
  console.log(job.status === "cancelled" ? "cancelled" : `finished before the cancel landed: ${job.status}`);
}

main().catch((err) => {
  console.error(err.message);
  process.exit(1);
});

